import csv
import sys


def count_nonempty(path):
    with open(path, newline="", encoding="utf-8") as f:
        reader = csv.reader(f)
        header = next(reader, None)
        if not header:
            return {}
        counts = {col: 0 for col in header}
        for row in reader:
            for i, value in enumerate(row):
                if i < len(header) and value.strip():
                    counts[header[i]] += 1
    return counts


if __name__ == "__main__":
    if len(sys.argv) != 2:
        print(f"用法: python {sys.argv[0]} <csv文件>")
        sys.exit(1)
    for col, count in count_nonempty(sys.argv[1]).items():
        print(f"{col}: {count}")
